/**
 * Pure helpers for the 800-line source-file guard.
 *
 * Rule (docs/CONVENTIONS.md §3): no hand-written file under `src/` exceeds
 * 800 lines. `src/worker-configuration.d.ts` is generated by
 * `wrangler types` and is exempt.
 *
 * Everything here is pure (paths and text in, verdicts out) so it is
 * unit-testable without filesystem access — the suite runs inside the
 * workers pool with no `node:fs`. The impure wrapper lives in
 * `scripts/check-source-file-size.mjs`, which walks `src/` and feeds
 * `{ path, text }` entries in.
 */

export const CHECK_NAME = "source-file-size";

/** Maximum lines for a hand-written file under `src/`. */
export const DEFAULT_LIMIT = 800;

/** Repo-relative paths exempt from the guard (generated, not hand-written). */
export const EXEMPT_PATHS = ["src/worker-configuration.d.ts"];

/**
 * Count lines `wc -l`-style: newline-terminated lines plus one for a trailing
 * partial line. Empty text is 0 lines.
 */
export function countLines(text) {
  const s = String(text);
  if (s === "") return 0;
  const parts = s.split("\n");
  return parts[parts.length - 1] === "" ? parts.length - 1 : parts.length;
}

export function isExempt(repoRelativePath) {
  return EXEMPT_PATHS.includes(repoRelativePath);
}

/**
 * Return the entries over `limit`, sorted by path. Exempt paths are skipped
 * regardless of size. Exactly `limit` lines passes — only `limit + 1` fails.
 */
export function findOversize(entries, { limit = DEFAULT_LIMIT } = {}) {
  const offenders = [];
  for (const { path, text } of entries) {
    if (isExempt(path)) continue;
    const lines = countLines(text);
    if (lines > limit) offenders.push({ path, lines });
  }
  return offenders.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
}

export function formatPassLog(checkedCount, limit) {
  return `${CHECK_NAME}: PASS — ${checkedCount} file(s) under src/ at or under ${limit} lines`;
}

export function formatFailureLog(offenders, limit) {
  const lines = [
    `${CHECK_NAME}: FAIL — ${offenders.length} file(s) under src/ exceed ${limit} lines:`,
  ];
  for (const { path, lines: n } of offenders) lines.push(`  ${path} (${n} lines)`);
  lines.push("Split the file into smaller modules; worker-configuration.d.ts is the only exemption.");
  return lines.join("\n");
}
